      )

mapper.update:
update schedule_table
set remain_number = remain_number - 1
where appointment_date = #{appointmentDate}
and department = #{department}
and remain_number > 0

update schedule_table
set remain_number = remain_number + 1
where appointment_date = #{appointmentDate}
  and department = #{department}
